  public static List<Gitlab.TypeID> parseMultipleTypeID(String s) throws ProtoException {
    List<Gitlab.TypeID> result = new ArrayList<>();
    for (String part : s.split(",")) {
      part = part.trim();
      if (!part.isEmpty()) {
        result.add(parseTypeID(part));
      }
    }
    return result;
  }

