  public static List<Gitlab.GitLabServiceRpcId> parseMultipleGitLabServiceRpcId(String s)
      throws ProtoException {
    List<Gitlab.GitLabServiceRpcId> result = new ArrayList<>();
    for (String part : s.split(",")) {
      part = part.trim();
      if (!part.isEmpty()) {
        result.add(parseGitLabServiceRpcId(part));
      }
    }
    return result;
  }

  public static Gitlab.GitlabConfigStateServiceRpcId parseGitlabConfigStateServiceRpcId(String s)
      throws ProtoException {
    if (s == null || s.isEmpty()) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Empty string cannot be parsed as "
              + Gitlab.GitlabConfigStateServiceRpcId.class.getSimpleName());
    }
    String normalized = s.toLowerCase().replace('_', '-');
    return switch (normalized) {
      case "all-accessors" ->
          Gitlab.GitlabConfigStateServiceRpcId.GITLAB_CONFIG_STATE_SERVICE_RPC_ID_ALL_ACCESSORS;
      case "all-mutators" ->
          Gitlab.GitlabConfigStateServiceRpcId.GITLAB_CONFIG_STATE_SERVICE_RPC_ID_ALL_MUTATORS;
      case "all-executors" ->
          Gitlab.GitlabConfigStateServiceRpcId.GITLAB_CONFIG_STATE_SERVICE_RPC_ID_ALL_EXECUTORS;
      case "get-config" ->
          Gitlab.GitlabConfigStateServiceRpcId.GITLAB_CONFIG_STATE_SERVICE_RPC_ID_GET_CONFIG;
      case "set-config" ->
          Gitlab.GitlabConfigStateServiceRpcId.GITLAB_CONFIG_STATE_SERVICE_RPC_ID_SET_CONFIG;
      case "watch-config" ->
          Gitlab.GitlabConfigStateServiceRpcId.GITLAB_CONFIG_STATE_SERVICE_RPC_ID_WATCH_CONFIG;
      default ->
          throw new ProtoException(
              ProtoException.INVALID_ARGUMENT,
              "Invalid "
                  + Gitlab.GitlabConfigStateServiceRpcId.class.getSimpleName()
                  + ": "
                  + s
                  + ", valid values are: "
                  + String.join(", ", gitlabConfigStateServiceRpcIdValidValues()));
    };
  }

