  public static Gitlab.MergeRequest mergeRequestFromBytes(byte[] data) throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    String dataStr = new String(data).trim();
    if (dataStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "empty data after trimming");
    }
    if (dataStr.startsWith("{") || dataStr.startsWith("[")) {
      try {
        return mergeRequestFromJson(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains(":") && !dataStr.contains("=")) {
      try {
        return mergeRequestFromYaml(dataStr);
      } catch (Exception e) {
        // Fall through to try other formats
      }
    }
    if (dataStr.contains("=")) {
      try {
        return mergeRequestFromToml(dataStr);
      } catch (Exception e) {
        // Fall through to try binary
      }
    }
    try {
      return mergeRequestFromBinary(data);
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL,
          "Failed to parse MergeRequest: unsupported format or invalid data: " + e.getMessage(),
          e);
    }
  }

