  public static Gitlab.MapEmpty mapEmptyFromJson(String json) throws ProtoException {
    if (json == null || json.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "json is null or empty");
    }
    try {
      Gitlab.MapEmpty.Builder builder = Gitlab.MapEmpty.newBuilder();
      return builder.build();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Failed to parse MapEmpty from JSON: " + e.getMessage(),
          e);
    }
  }

  public static Gitlab.MapEmpty mapEmptyFromBinary(byte[] data) throws ProtoException {
    if (data == null || data.length == 0) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "data is null or empty");
    }
    try {
      return Gitlab.MapEmpty.parseFrom(data);
    } catch (InvalidProtocolBufferException e) {
      throw new ProtoException(
          ProtoException.INVALID_ARGUMENT,
          "Failed to parse MapEmpty from binary: " + e.getMessage(),
          e);
    }
  }

  public static String mapEmptyToYaml(Gitlab.MapEmpty msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "MapEmpty is null");
    }
    try {
      String json = mapEmptyToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      Yaml yaml = new Yaml();
      return yaml.dump(map);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to serialize MapEmpty to YAML: " + e.getMessage(), e);
    }
  }

  public static Gitlab.MapEmpty mapEmptyFromYaml(String yamlStr) throws ProtoException {
    if (yamlStr == null || yamlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "yamlStr is null or empty");
    }
    try {
      Yaml yaml = new Yaml();
      @SuppressWarnings("unchecked")
      Map<String, Object> map = (Map<String, Object>) yaml.load(yamlStr);
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return mapEmptyFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to parse MapEmpty from YAML: " + e.getMessage(), e);
    }
  }

  public static String mapEmptyToToml(Gitlab.MapEmpty msg) throws ProtoException {
    if (msg == null) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "MapEmpty is null");
    }
    try {
      String json = mapEmptyToJson(msg);
      Gson gson = new Gson();
      Map<String, Object> map =
          gson.fromJson(
              json, new com.google.gson.reflect.TypeToken<Map<String, Object>>() {}.getType());
      StringBuilder toml = new StringBuilder();
      if (map == null || map.isEmpty()) {
        return "# Empty MapEmpty\n";
      }
      for (Map.Entry<String, Object> entry : map.entrySet()) {
        toml.append(entry.getKey()).append(" = ");
        if (entry.getValue() instanceof String) {
          toml.append("\"").append(entry.getValue()).append("\"");
        } else {
          toml.append(entry.getValue());
        }
        toml.append("\n");
      }
      return toml.toString();
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to serialize MapEmpty to TOML: " + e.getMessage(), e);
    }
  }

  public static Gitlab.MapEmpty mapEmptyFromToml(String tomlStr) throws ProtoException {
    if (tomlStr == null || tomlStr.isEmpty()) {
      throw new ProtoException(ProtoException.INVALID_ARGUMENT, "tomlStr is null or empty");
    }
    try {
      Toml toml = new Toml().read(tomlStr);
      Map<String, Object> map = toml.toMap();
      Gson gson = new Gson();
      String json = gson.toJson(map);
      return mapEmptyFromJson(json);
    } catch (ProtoException e) {
      throw e;
    } catch (Exception e) {
      throw new ProtoException(
          ProtoException.INTERNAL, "Failed to parse MapEmpty from TOML: " + e.getMessage(), e);
    }
  }

