  // ============ Merge ============
  public static Gitlab.Config.Builder mergeConfig(Gitlab.Config dst, Gitlab.Config src) {
    Gitlab.Config.Builder builder = dst.toBuilder();
    if (dst.getApiToken().isEmpty()) {
      builder.setApiToken(src.getApiToken());
    }
    return builder;
  }

  public static Gitlab.RateLimitInfo.Builder mergeRateLimitInfo(
      Gitlab.RateLimitInfo dst, Gitlab.RateLimitInfo src) {
    Gitlab.RateLimitInfo.Builder builder = dst.toBuilder();
    if (dst.getLimit() == 0) {
      builder.setLimit(src.getLimit());
    }
    if (dst.getRemaining() == 0) {
      builder.setRemaining(src.getRemaining());
    }
    if (dst.getObserved() == 0) {
      builder.setObserved(src.getObserved());
    }
    if (dst.getResetAt() == 0) {
      builder.setResetAt(src.getResetAt());
    }
    if (dst.getResetTime().isEmpty()) {
      builder.setResetTime(src.getResetTime());
    }
    return builder;
  }

  public static Gitlab.PaginationInfo.Builder mergePaginationInfo(
      Gitlab.PaginationInfo dst, Gitlab.PaginationInfo src) {
    Gitlab.PaginationInfo.Builder builder = dst.toBuilder();
    if (dst.getPage() == 0) {
      builder.setPage(src.getPage());
    }
    if (dst.getPerPage() == 0) {
      builder.setPerPage(src.getPerPage());
    }
    if (dst.getTotal() == 0) {
      builder.setTotal(src.getTotal());
    }
    if (dst.getTotalPages() == 0) {
      builder.setTotalPages(src.getTotalPages());
    }
    if (!dst.getHasNextPage()) {
      builder.setHasNextPage(src.getHasNextPage());
    }
    if (dst.getNextPageUrl().isEmpty()) {
      builder.setNextPageUrl(src.getNextPageUrl());
    }
    return builder;
  }

